#include "study_observer.h"
#include "instrumented_native/flowCUDA.cu"
#include <iostream>
#include <iomanip>
struct Fixture{int w,h,stride,levels,warps,solver;float alpha;std::vector<float>a,b;};
template<class T>std::vector<T>rd(std::ifstream&f,size_t n){std::vector<T>v(n);f.read((char*)v.data(),n*sizeof(T));if(!f)throw std::runtime_error("short fixture/oracle");return v;}
Fixture fixture(const std::string&path){std::ifstream f(path,std::ios::binary);auto h=rd<uint32_t>(f,8);auto z=rd<float>(f,1);if(h[0]!=0x4f463537||h[7]!=2*h[3]*h[2])throw std::runtime_error("bad fixture header");Fixture a{int(h[1]),int(h[2]),int(h[3]),int(h[4]),int(h[5]),int(h[6]),z[0],rd<float>(f,h[3]*h[2]),rd<float>(f,h[3]*h[2])};if(f.peek()!=EOF)throw std::runtime_error("trailing fixture");return a;}
void main_case(const std::string&root,const std::string&name,const std::string&folder,int trial,int case_id){auto a=fixture(root+"/"+name+"_fixture.bin");auto&s=study::state();s.case_id=case_id;s.next=0;std::vector<float>u(a.a.size()),v(a.a.size());if(case_id==0){s.mark=std::chrono::steady_clock::now();s.running=true;}ComputeFlowCUDA(a.a.data(),a.b.data(),a.w,a.h,a.stride,a.alpha,a.levels,a.warps,a.solver,u.data(),v.data());study::check(cudaDeviceSynchronize());if(case_id==0){s.seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-s.mark).count();s.running=false;}if(!trial)return;
 std::ofstream host(folder+"/cuda_trial"+std::to_string(trial)+"_case"+std::to_string(case_id)+".host.bin",std::ios::binary);for(auto*p:{&u,&v})study::bytes(host,p->data(),p->size()*4);std::vector<float>active;for(auto*p:{&u,&v})for(int y=0;y<a.h;y++)active.insert(active.end(),p->begin()+y*a.stride,p->begin()+y*a.stride+a.w);std::ifstream f(root+"/"+name+"_oracle.bin",std::ios::binary);auto header=rd<uint32_t>(f,2);if(header[0]!=a.w||header[1]!=a.h)throw std::runtime_error("bad reference shape");auto reference=rd<double>(f,active.size());if(f.peek()!=EOF)throw std::runtime_error("trailing oracle");std::vector<double>bounds(reference.size());for(size_t i=0;i<bounds.size();i++)bounds[i]=.05+.001*std::abs(reference[i]);study::compare(active,reference,bounds);
 std::ifstream old(root+"/"+name+"_legacyCPU.bin",std::ios::binary);auto oldheader=rd<uint32_t>(old,2);auto legacy=rd<float>(old,active.size());double delta=0;for(size_t i=0;i<active.size();i++)delta+=std::abs(double(active[i])-legacy[i]);double oldL1=delta/(a.w*a.h);s.output.insert(s.output.end(),active.begin(),active.end());std::cout<<"STUDY_SCIENCE {\"case\":"<<case_id<<",\"source_CPU_meanL1\":"<<std::setprecision(17)<<oldL1<<",\"source_CPU_threshold\":0.05,\"boundary_policies_differ\":true,\"independent_max_abs\":"<<s.max_abs<<",\"independent_max_bound_fraction\":"<<s.max_fraction<<"}\n";
 // CPU source's different negative-coordinate policy remains separately described.
 if(case_id==1)for(float x:active)s.valid&=std::abs(x)<=.05f;
}
void primitive_case(const std::string&root,int trial){auto&s=study::state();s.case_id=2;s.next=0;std::ifstream f(root+"/primitive_fixture.bin",std::ios::binary);auto h=rd<uint32_t>(f,2);if(h[0]!=0x4f465052||h[1]!=9)throw std::runtime_error("bad primitive fixture");std::vector<float*>ptr;std::vector<std::vector<float>>host;std::vector<int>w,ht,stride;
 for(int i=0;i<9;i++){auto meta=rd<uint32_t>(f,4);if(meta[0]!=i)throw std::runtime_error("primitive input order");int n=meta[2]*meta[3];host.push_back(rd<float>(f,n));float*p;study::allocate(&p,n*4);study::check(cudaMemcpy(p,host.back().data(),n*4,cudaMemcpyHostToDevice));ptr.push_back(p);w.push_back(meta[1]);ht.push_back(meta[2]);stride.push_back(meta[3]);if(trial){s.prefix.insert(s.prefix.end(),{float(i),float(w.back()),float(ht.back()),float(stride.back()),float(n)});auto actual=study::read(p,n);s.prefix.insert(s.prefix.end(),actual.begin(),actual.end());}}
 if(f.peek()!=EOF)throw std::runtime_error("trailing primitive input");if(trial)s.prefix.push_back(.2f);float*o,*x,*y,*z;study::allocate(&o,256*64*4);study::allocate(&x,256*32*4);study::allocate(&y,256*32*4);study::allocate(&z,256*32*4);size_t output_start=s.output.size();
 Downscale(ptr[0],64,32,256,32,16,256,o);if(trial)study::append_active(o,32,16,256);
 Upscale(ptr[0],64,32,256,128,64,256,2.f,o);if(trial)study::append_active(o,128,64,256);
 WarpImage(ptr[1],64,32,256,ptr[2],ptr[3],o);if(trial)study::append_active(o,64,32,256);
 ComputeDerivatives(ptr[0],ptr[1],64,32,256,x,y,z);if(trial)for(auto*p:{x,y,z})study::append_active(p,64,32,256);
 Add(ptr[0],ptr[1],256*32,o);study::check(cudaDeviceSynchronize());if(trial){auto a=study::read(o,256*32);s.output.insert(s.output.end(),a.begin(),a.end());}
 float*du,*dv;study::allocate(&du,256*13*4);study::allocate(&dv,256*13*4);
 SolveForUpdate(ptr[4],ptr[5],ptr[6],ptr[7],ptr[8],65,13,256,.2f,du,dv);study::check(cudaDeviceSynchronize());if(trial){study::append_active(du,65,13,256);study::append_active(dv,65,13,256);}
 study::check(cudaMemset(ptr[4],0,256*13*4));study::check(cudaMemset(ptr[5],0,256*13*4));if(trial)for(auto*p:{ptr[4],ptr[5]}){auto a=study::read(p,256*13);s.prefix.insert(s.prefix.end(),a.begin(),a.end());}
 float*oldU=ptr[4],*oldV=ptr[5],*newU=du,*newV=dv;for(int i=0;i<500;i++){SolveForUpdate(oldU,oldV,ptr[6],ptr[7],ptr[8],65,13,256,.2f,newU,newV);Swap(oldU,newU);Swap(oldV,newV);}study::check(cudaDeviceSynchronize());if(trial){study::append_active(oldU,65,13,256);study::append_active(oldV,65,13,256);std::ifstream oracle(root+"/primitive_oracle.bin",std::ios::binary);auto oh=rd<uint32_t>(oracle,3);if(oh[0]!=0x4f464f52||oh[1]!=11||oh[2]!=28468)throw std::runtime_error("bad primitive oracle");auto sizes=rd<uint32_t>(oracle,oh[1]);auto reference=rd<double>(oracle,oh[2]),bounds=rd<double>(oracle,oh[2]);std::vector<float>actual(s.output.begin()+output_start,s.output.end());study::compare(actual,reference,bounds);}
 for(auto*p:ptr)study::release(p);for(auto*p:{o,x,y,z,du,dv})study::release(p);
}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("assetsroot and persistentfolder required");std::string root=argv[1],folder=argv[2];std::filesystem::create_directories(folder);auto&s=study::state();for(int trial=0;trial<=5;trial++){s.capture=trial>0;s.running=false;s.valid=true;s.seconds=s.max_abs=s.max_fraction=0;s.checked=0;s.prefix.clear();s.output.clear();if(trial){s.raw.open(folder+"/cuda_trial"+std::to_string(trial)+".physical.bin",std::ios::binary);s.layout.open(folder+"/cuda_trial"+std::to_string(trial)+".layout.jsonl");}main_case(root,"original_pair",folder,trial,0);main_case(root,"identity_partial",folder,trial,1);primitive_case(root,trial);if(!s.live.empty())throw std::runtime_error("unreleased buffer");if(!trial)continue;s.raw.close();s.layout.close();size_t prefix=s.prefix.size();s.prefix.insert(s.prefix.end(),s.output.begin(),s.output.end());std::string path="trial"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);study::bytes(out,s.prefix.data(),s.prefix.size()*4);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"independent_max_bound_fraction\":%.17g,\"independent_checked_values\":%llu,\"input_prefix_values\":%zu,\"timing_region\":\"fullsource_ComputeFlowCUDA640x480_5levels3warps500Jacobi_alloc_copies_free_observer_split\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,s.seconds,s.valid?"true":"false",s.prefix.size(),s.max_abs,s.max_fraction,(unsigned long long)s.checked,prefix,path.c_str(),s.prefix.size());fflush(stdout);if(!s.valid)return 1;}return 0;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}
